// Keys the load generates: every run of the program makes its own pair.
var crypto = require("crypto");
var ecdh = crypto.createECDH("prime256v1");
var group = crypto.getDiffieHellman("modp14");
module.exports = {
  publicKey: ecdh.generateKeys("hex"),
  groupKey: group.generateKeys("hex").slice(0, 64),
};
